/// Send a batch of 2 to 15 orders, all for a single trading pair. The whole batch is validated before submission -- one invalid order rejects the batch. Once submitted, individual orders that fail pre-match checks (e.g. insufficient funds) are rejected individually and the rest of the batch is still processed.
///
/// **API Key Permissions Required:** `Orders and trades - Create & modify orders` and `Orders and trades - Cancel & close orders`
#[derive(Clone)]
pub struct AddOrderBatch {
    core: Arc<dyn HttpEndpoint<SpotMeta>>,
}

impl AddOrderBatch {
    pub fn new(core: Arc<dyn HttpEndpoint<SpotMeta>>) -> Self {
        Self { core }
    }

    /// Send a batch of 2 to 15 orders, all for a single trading pair. The whole batch is validated before submission -- one invalid order rejects the batch. Once submitted, individual orders that fail pre-match checks (e.g. insufficient funds) are rejected individually and the rest of the batch is still processed.
    ///
    /// **API Key Permissions Required:** `Orders and trades - Create & modify orders` and `Orders and trades - Cancel & close orders`
    ///
    /// See <https://docs.kraken.com/api-reference/trading/add-order-batch>.
    pub async fn add_order_batch(
        &self,
        request: Request,
        options: CallOptions,
    ) -> Result<OrderBatchAdded> {
        let raw = self.add_order_batch_raw(request, options).await?;
        decode(raw)
    }

    /// `add_order_batch` without validation: the wire body as it came.
    pub async fn add_order_batch_raw(
        &self,
        request: Request,
        options: CallOptions,
    ) -> Result<serde_json::Value> {
        let meta = SpotMeta { signed: Some(true) };
        let call = HttpCall {
            method: Some("POST"),
            path: "/0/private/AddOrderBatch",
            request: Some(dump(&request)?),
            meta: &meta,
            options,
        };
        self.core.request(call).await
    }
}
